risks = {
    "malware": {"threat": 0.7, "vulnerability": 0.8, "impact": 100000},
    "insider_threat": {"threat": 0.2, "vulnerability": 0.6, "impact": 500000}
}
for risk_name, values in risks.items():
    risk_score = values["threat"] * values["vulnerability"] * values["impact"]
    print(f"{risk_name}: {risk_score:,.0f}")
